-- DIA A DIA fictício da RBN 94,3: visitas, tarefas de agenda e negócios em TODOS os dias úteis.
-- Complementa 20261029110000 (carga principal) e 20261029130000 (visitas). Rode depois delas.
-- Tudo sai no script de limpeza 20261029110100 (leads demo_seed, jobs DEMO-SEED, lancamentos DEMO,
-- visitas e tarefas ligadas aos anunciantes demo). Metas 2026 da RBN são reajustadas ao novo volume.

DO $demo$
DECLARE
  v_emp uuid; v_count int; v_users uuid[]; v_unid text[]; v_nomes text[]; v_u uuid; v_cli bigint; v_lead bigint;
BEGIN
  SELECT count(*) INTO v_count FROM empresas WHERE nome ILIKE '%rbn%';
  IF v_count <> 1 THEN RAISE EXCEPTION 'Esperava 1 empresa com "RBN" no nome, achou %. Ajuste o filtro.', v_count; END IF;
  SELECT id INTO v_emp FROM empresas WHERE nome ILIKE '%rbn%';
  IF NOT EXISTS (SELECT 1 FROM clientes WHERE empresa_id = v_emp AND observacao_risco = 'DEMO-SEED') THEN RAISE EXCEPTION 'Rode antes a carga principal (20261029110000).'; END IF;
  IF EXISTS (SELECT 1 FROM leads WHERE empresa_id = v_emp AND origem = 'demo_seed' AND descricao LIKE 'DEMO-RBN-D%') THEN RAISE EXCEPTION 'Dia a dia demo já carregado.'; END IF;
  v_users := ARRAY(SELECT id FROM profiles WHERE empresa_id = v_emp ORDER BY (cargo = 'diretor') DESC, id);
  v_unid := ARRAY(SELECT nome FROM unidades WHERE empresa_id = v_emp ORDER BY nome);
  IF array_length(v_unid, 1) IS NULL THEN v_unid := ARRAY['RBN 94,3']; END IF;
  v_nomes := ARRAY['Carla Mendes', 'Rafael Souza', 'Juliana Prates'];

